  gap: 0.6rem;
  width: 100%;
}

.arabic-input {
  flex: 1;
  padding: 0.8rem 1.1rem;
  font-size: 1.25rem;
  background: var(--card);
  color: var(--foreground);
  border: 1.5px solid var(--border);
  border-radius: var(--radius);
  outline: none;
  transition: all 0.15s ease;
  direction: rtl;
  text-align: right;
  font-family: inherit;
}

.arabic-input:focus {
  border-color: color-mix(in oklab, #d4af37 75%, var(--ring));
  box-shadow: 0 0 0 3px color-mix(in oklab, #d4af37 25%, transparent);
}

.submit-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  padding: 0 1.35rem;
  border-radius: var(--radius);
  background: color-mix(in oklab, #d4af37 80%, var(--primary));
  color: #111;
  font-weight: 600;
  font-size: 1rem;
  border: none;
  cursor: pointer;
  transition: all 0.15s ease;
}

.submit-btn:hover {
  filter: brightness(1.1);
}

.typing-hint {
  font-size: 0.85rem;
}

/* Post-Answer Feedback Banner */
.verdict-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.85rem 1.25rem;
  border-radius: var(--radius);
  border: 1.5px solid var(--border);
